library ArrayUtils {

    function max(uint[] memory values)
        internal pure
        returns(uint)
    {
        uint maximum = values[0];

        for(uint i = 1; i < values.length; i++) {
            if(values[i] > maximum) {
                maximum = values[i];
            }
        }

        return maximum;
    }
}

contract ArrayExample {

    using ArrayUtils for uint[];

    function getMaximum(uint[] memory values)
        public pure
        returns(uint)
    {
        return values.max();
    }
}

