// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract EtherReceiver {

    event Received(
        address sender,
        uint amount
    );

    receive() external payable {
        emit Received(
            msg.sender,
            msg.value
        );
    }

    fallback() external payable {
        // handles unmatched calls
    }

    function getBalance()
        public view
        returns(uint)
    {
        return address(this).balance;
    }
}
